package de.kumpewo.autohotkey.psi;

import com.intellij.psi.tree.IElementType;
import de.kumpewo.autohotkey.AhkLanguage;
import org.jetbrains.annotations.NonNls;
import org.jetbrains.annotations.NotNull;

/** Type of the composite PSI elements generated by Grammar-Kit (constants in {@code AhkTypes}). */
public class AhkElementType extends IElementType {
    public AhkElementType(@NotNull @NonNls String debugName) {
        super(debugName, AhkLanguage.INSTANCE);
    }
}
